-- Sales CRM — run this whole file once in the Supabase SQL Editor. Safe to re-run.
create table if not exists users (id bigint generated by default as identity primary key, username text unique not null, name text not null, password text not null, role text not null default 'sales' check (role in ('admin','manager','sales')), phone text default '', manager_id bigint references users(id), active boolean not null default true, must_change boolean not null default true, created_at timestamptz default now());
create table if not exists leads (id bigint generated by default as identity primary key, company text not null, name text not null, firm text default '', phone text default '', alt_phone text default '', email text default '', city text default '', source text default '', product text default '', requirement text default '', value numeric default 0, stage text not null default 'New', lost_reason text default '', assigned_to bigint references users(id), created_by bigint references users(id), next_followup_at timestamptz, last_contact_at timestamptz, closed_at timestamptz, notes text default '', created_at timestamptz default now(), updated_at timestamptz default now());
create index if not exists leads_owner on leads(assigned_to);
create index if not exists leads_phone on leads(phone);
create index if not exists leads_next on leads(next_followup_at);
create table if not exists activities (id bigint generated by default as identity primary key, lead_id bigint not null references leads(id) on delete cascade, user_id bigint references users(id), kind text not null, note text default '', stage_from text default '', stage_to text default '', next_followup_at timestamptz, created_at timestamptz default now());
create index if not exists act_lead on activities(lead_id);
create table if not exists app_settings (key text primary key, value text);
-- Lock tables: only the app's secret key (which bypasses RLS) can read/write.
alter table users enable row level security;
alter table leads enable row level security;
alter table activities enable row level security;
alter table app_settings enable row level security;
